        "DEFINISI": [
          "Akasa adalah unsur kelima dari Panca Maha Bhuta (lima unsur pembentuk alam semesta dan tubuh manusia dalam kosmologi Hindu Bali), yaitu unsur eter atau ruang/rongga yang menurut mantra Panca Maha Bhuta berpadanan dengan indra sabda (pendengaran/suara). Dalam konteks Ngaben, lingga sarira Sang Pitara (wujud halus roh leluhur) diyakini berunsur bayu dan akasa; unsur akasa didekati lewat sarana kotak kosong berisi telur, karena akasa dipandang sebagai unsur yang \"kosong namun bernas\" (halus tapi berisi), dan bersama unsur teja serta bayu dikembalikan ke asalnya (Sang Pancamahabutha) melalui pembakaran jenazah."
        ],
