        "DEFINISI": [
          "Banten Sesayut adalah salah satu jenis banten (sesajen) umum dalam upacara Hindu Bali, dihaturkan sebagai permohonan keselamatan, kesucian, dan penolak bala, serta dipakai hampir di semua jenis upacara/yadnya. Dalam konteks Ngaben, Ayaban Sesayut diberikan oleh sulinggih kepada putra-putri yang berupacara setelah pelaksanaan Saji Tarpana, sebagai bagian dari upacara Ngroras yang diiringi potong gigi."
        ]
