        "DEFINISI": [
          "Bali Dataran adalah sebutan untuk masyarakat Bali yang mendiami wilayah dataran dan menerima pengaruh kuat tradisi Hindu-Majapahit pasca runtuhnya kerajaan Hindu-Majapahit di Jawa, berbeda dengan Bali Aga, masyarakat pegunungan (seperti di Trunyan) yang mempertahankan tradisi asli yang lebih kuno. Dalam konteks Ngaben, masyarakat Bali Dataran umumnya melaksanakan upacara dengan sarana yang mewah dan megah seperti bade (menara pengusung jenazah) dan petulangan (wadah kremasi berbentuk hewan), berbeda dengan Bali Aga yang cenderung lebih sederhana dan terkadang tidak menggunakan pembakaran fisik jenazah secara masif."
        ],
