          "value": "Banten Teben adalah sebutan umum untuk sajen yang diletakkan di bagian bawah atau dekat lantai (teben), lazim dihaturkan dalam berbagai upacara Hindu Bali. Dalam konteks Ngaben, Banten Teben diletakkan dekat kaki jenazah, dihaturkan disertai sembah bhakti (muspa) segenap keluarga sebagai bagian dari Saji Tarpana.",
