        "DEFINISI": [
          "\"Eteh-eteh\" secara umum berarti perlengkapan atau kelengkapan suatu keperluan dalam bahasa Bali. Dalam konteks Ngaben, eteh-eteh adalah kelengkapan sawa yang dimohonkan dari sulinggih/griya, antara lain berupa angkeb baga/purus, angkeb rai, bunga, kain kuning untuk saput/selendang, kain putih berisi pis bolong 11 kepeng, kain putih untuk saput, kamben, kawangen, leluwur, pangulungan, rantasan kain putih-kuning dan kain anyar, sabuk, samsam, tapih, tatindih, serta udeng."
        ]
