      "isolated": false,
      "literals": {
        "DEFINISI": [
          "Bagian bibir pada jenazah yang menjadi sasaran dalam rangkaian upacara Potong Gigi simbolis pasca-kematian: pedangal dari kayu dapdap ditaruh di baliknya sebagai penopang gigi, kuncup teratai digosokkan padanya sebagai pengganti kikir bila bibir jenazah terkatup, dan tembakau diusapkan untuk membersihkannya sebelum gigi jenazah diolesi madu."
        ],
        "DIBERSIHKAN_DENGAN": [
          "tembakau diusapkan pada bibir"
        ]
      },
