      "id": "lingga_sarira_pitara",
      "label": "lingga sarira pitara",
      "type": "KONSEP_FILOSOFIS",
      "degree": 2,
      "isolated": false,
      "literals": {
        "DEFINISI": [
          "Lingga sarira (sukshma sarira) adalah salah satu dari tiga badan yang menyusun diri manusia menurut ajaran Hindu (Tri Sarira), yakni badan halus/astral yang tersusun dari unsur-unsur seperti bayu (angin) dan akasa (ether/ruang) dan tetap ada setelah badan kasar (stula sarira) mati. Dalam konteks Ngaben, lingga sarira Sang Pitara (roh leluhur mendiang) ini didekati dan disucikan lewat sarana seperti kipas dan telur dalam rangkaian upacara."
        ]
      },
