      "id": "pura_desa",
      "label": "pura desa",
      "type": "BANGUNAN_RITUAL",
      "degree": 2,
      "isolated": false,
      "literals": {
        "DEFINISI": [
          "Pura Desa adalah salah satu pura Kahyangan Tiga (bersama Pura Puseh dan Pura Dalem) yang menjadi pusat pemujaan komunitas desa adat di Bali, secara tradisional dikaitkan dengan pemujaan Bhatara Brahma. Dalam konteks Ngaben, Pura Desa menjadi salah satu tempat memohon Tirtha Kahyangan Tiga bersama Pura Puseh, Pura Dalem, dan Pura Mrajapti, tirtha yang wajib ada dalam kelengkapan upacara Ngaben."
        ]
      },
