      "degree": 2,
      "isolated": false,
      "literals": {
        "DEFINISI": [
          "Pura Mrajapti (Prajapati) adalah pura yang umumnya berlokasi di dekat setra (kuburan) dan dikaitkan dengan pemujaan kekuatan niskala yang menguasai proses kematian dan peleburan unsur jasmani, di banyak desa adat dianggap bagian dari kompleks Pura Dalem. Dalam konteks Ngaben, Pura Mrajapti menjadi salah satu tempat memohon Tirtha Kahyangan Tiga bersama Pura Desa, Pura Puseh, dan Pura Dalem, tirtha yang wajib ada dalam kelengkapan upacara Ngaben."
        ]
      },
