      "type": "KONSEP_HUKUM_ADAT",
      "degree": 2,
      "isolated": false,
      "literals": {
        "DEFINISI": [
          "Dalam konteks kalender Bali, Wayang adalah salah satu dari 30 wuku (minggu bertema tujuh hari) dalam siklus Pawukon 210 hari -- bukan seni pertunjukan wayang kulit -- yang berjalan berdampingan dengan kalender sasih untuk menentukan hari baik atau buruk suatu kegiatan. Dalam konteks Ngaben, wuku Wayang bertepatan dengan sasih Kapat dan Kadasa -- sasih Kapat dipercaya sebagai waktu terbukanya alam dewa dan baik untuk Dewa Yadnya, sedangkan sasih Kadasa baik untuk Pitra Yadnya namun dipantang untuk membakar jenazah karena bertepatan dengan pesamuhan para dewa; hari Budha (Rabu) pada wuku Wayang tetap termasuk salah satu dewasa yang diperbolehkan untuk Ngaben."
        ]
      },
